window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-62f127f6ea4ffcff"]={"versions": [{"id": "FIG-62f127f6ea4ffcff", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation der AUTOSAR-Laufzeitumgebung (RTE). Das Diagramm stellt das Inter-ECU-Kommunikationsszenario für eine explizite Sender-Receiver-Kommunikation dar, bei der ein VariableDataPrototype mit Ereignissemantik (<code>queued swImplPolicy</code>) über Port <code>p</code> und Datenelement <code>e</code> übertragen wird. Die Empfangsseite verwendet den nicht-blockierenden Empfangsmechanismus über Argument (<code>dataReceivePointByArgument</code>) ohne WaitPoint am zugehörigen <code>DataReceivedEvent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Sender Application</code> (Software-Komponente / SWC auf Sender-ECU)\n</li><li><code>Sender&#x27;s RTE</code> (Laufzeitumgebung der Sender-ECU)\n</li><li><code>Sender&#x27;s COM / Netwok / Receiver&#x27;s COM</code> (Kombinierte Kommunikationsinfrastruktur aus COM-Modulen und Netzwerkübertragung)\n</li><li><code>Receiver&#x27;s RTE</code> (Laufzeitumgebung der Empfänger-ECU)\n</li><li><code>Receiver application</code> (Software-Komponente / SWC auf Empfänger-ECU)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Rte_Receive_p_e</code>: RTE-API zum Auslesen des Warteschlangeninhalts über OUT-Parameter\n</li><li><code>Rte_Send_p_e</code>: RTE-API zum Einreihen/Senden des Datenelements\n</li><li><code>Com_SendSignal</code>: BSW-COM-Schnittstelle zum Absenden des Signals\n</li><li><code>Rte_COMCbk_&lt;sn&gt;</code>: Signal-spezifische COM-Callback-Funktion zur Benachrichtigung der Empfänger-RTE\n</li><li><code>Com_ReceiveSignal</code>: BSW-COM-Schnittstelle zum Abholen des empfangenen Signals aus dem COM-Puffer\n</li><li>Statuswerte: <code>RTE_E_NO_DATA</code>, <code>E_OK</code>, <code>RTE_E_OK</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialisierung: Die RTE-Warteschlange für das Ereignis <code>p_e</code> wird initialisiert/geleert (Notiz 1).\n</li><li>Vorzeitiger Leseversuch: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e</code> auf. Da die Warteschlange leer ist, kehrt der Aufruf unmittelbar mit <code>RTE_E_NO_DATA</code> zurück (Notiz 2).\n</li><li>Sendevorgang: Die Sender-Applikation ruft <code>Rte_Send_p_e</code> auf. Die Sender-RTE leitet das Datenelement via <code>Com_SendSignal</code> an das COM-Modul weiter, erhält <code>E_OK</code> zurück und bestätigt der Applikation mit <code>RTE_E_OK</code>.\n</li><li>Signalempfang &amp; COM-Notification: Nach der Netzwerkübertragung ruft das empfangende COM-Modul den Callback <code>Rte_COMCbk_&lt;sn&gt;</code> der Empfänger-RTE auf (Notiz 3).\n</li><li>Signalübernahme in RTE-Queue: Die Empfänger-RTE fragt die Daten mittels <code>Com_ReceiveSignal</code> ab, quittiert mit <code>E_OK</code> und legt das empfangene Ereigniselement <code>e</code> in der internen RTE-Warteschlange für <code>e</code> ab (Notiz 4).\n</li><li>Erfolgreicher Empfang: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e</code> auf. Die Empfänger-RTE entnimmt das Ereigniselement aus der Warteschlange, kopiert es in den OUT-Parameter der Applikation (Notiz 5, 6) und liefert <code>RTE_E_OK</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Soll-Verhalten für asynchrone bzw. gepufferte (queued) Inter-ECU-S/R-Kommunikation. Bei leerer Queue muss der Status <code>RTE_E_NO_DATA</code> synchron zurückgegeben werden, ohne die aufrufende Task zu blockieren. Die Entkopplung zwischen Bus-Eingang und Applikationskonsum erfolgt über eine RTE-interne FIFO-Warteschlange, die über den COM-Callback befüllt und durch das applikationsseitige Polling per OUT-Parameter geleert wird.</p>"}, {"id": "FIG-706f2e28c75f8895", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation der AUTOSAR-Laufzeitumgebung (RTE). Das Diagramm stellt das Inter-ECU-Kommunikationsszenario für eine explizite Sender-Receiver-Kommunikation mit Transformern (Serialization/Transformation) dar. Ein VariableDataPrototype mit Ereignissemantik (<code>queued swImplPolicy</code>) wird über Port <code>p</code> und Datenelement <code>e</code> übertragen. Die Empfangsseite verwendet den nicht-blockierenden Empfangsmechanismus über Argument (<code>dataReceivePointByArgument</code>) ohne WaitPoint am zugehörigen <code>DataReceivedEvent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Sender Application</code> (Software-Komponente auf Sender-ECU)\n</li><li><code>Sender&#x27;s RTE</code> (Laufzeitumgebung der Sender-ECU)\n</li><li><code>Sender&#x27;s Transformer</code> (Transformationsmodul/Serialisierung der Sender-ECU)\n</li><li><code>Sender&#x27;s COM / Netwok / Receiver&#x27;s COM</code> (Kommunikationsinfrastruktur aus COM-Modulen und Netzwerkübertragung)\n</li><li><code>Receiver&#x27;s Transformer</code> (Invertiertes Transformationsmodul/Deserialisierung der Empfänger-ECU)\n</li><li><code>Receiver&#x27;s RTE</code> (Laufzeitumgebung der Empfänger-ECU)\n</li><li><code>Receiver application</code> (Software-Komponente auf Empfänger-ECU)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>Rte_Receive_p_e()</code>: Nicht-blockierende Lese-API der RTE\n</li><li><code>Rte_Send_p_e()</code>: Sende-API der RTE\n</li><li><code>Xfrm_&lt;name&gt;()</code>: Transformer-Aufruf zur Serialisierung/Transformation der Nutzdaten\n</li><li><code>Com_SendSignal()</code>: COM-API zur Signalübertragung\n</li><li><code>Rte_COMCbk_&lt;sn&gt;()</code>: COM-Callback zur Benachrichtigung der Empfänger-RTE\n</li><li><code>Com_ReceiveSignal()</code>: COM-API zum Abrufen des empfangenen Signals\n</li><li><code>Xfrm_Inv_&lt;name&gt;()</code>: Invertierter Transformer-Aufruf zur Deserialisierung/Retransformation\n</li><li>Rückgabewerte: <code>RTE_E_NO_DATA()</code>, <code>E_OK()</code>, <code>RTE_E_OK()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialisierung: Die RTE-Warteschlange für das Ereignis <code>p_e</code> wird initialisiert/geleert (Notiz 1).\n</li><li>Vorzeitiger Leseversuch: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf. Da die Warteschlange leer ist, liefert die RTE synchron <code>RTE_E_NO_DATA()</code> an die Empfänger-Applikation zurück (Notiz 2).\n</li><li>Sendevorgang &amp; Transformation: Die Sender-Applikation ruft <code>Rte_Send_p_e()</code> auf. Die Sender-RTE transformiert die Daten über <code>Xfrm_&lt;name&gt;()</code> und übergibt das Ergebnis mittels <code>Com_SendSignal()</code> an das COM-Modul, welches mit <code>E_OK()</code> quittiert. Anschließend bestätigt die RTE der Sender-Applikation den Aufruf mit <code>RTE_E_OK()</code>.\n</li><li>Signalempfang &amp; COM-Notification: Nach der Netzwerkübertragung ruft das Empfänger-COM die Callback-Funktion <code>Rte_COMCbk_&lt;sn&gt;()</code> der Empfänger-RTE auf (Notiz 3).\n</li><li>Signalübernahme in RTE-Queue: Die Empfänger-RTE holt die transformierten Daten via <code>Com_ReceiveSignal()</code> ab, quittiert mit <code>E_OK()</code> und reiht das empfangene Ereigniselement <code>e</code> in die interne RTE-Warteschlange ein (Notiz 4).\n</li><li>Erfolgreicher Empfang &amp; Retransformation: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf. Die RTE entnimmt den Eintrag aus der Queue, transformiert ihn mittels <code>Xfrm_Inv_&lt;name&gt;()</code> zurück (Notiz 5), kopiert das rekonstruierte Ereigniselement in den OUT-Parameter der Applikation (Notiz 6) und liefert <code>RTE_E_OK()</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Zusammenspiel von RTE, COM und der AUTOSAR-Transformer-Kette bei queued S/R-Kommunikation. Die Transformation findet senderseitig vor der Übergabe an das Kommunikationsmodul statt, während die inverse Transformation auf Empfängerseite verzögert beim Abruf durch die Applikation (<code>Rte_Receive_p_e()</code>) erfolgt. Dadurch speichert die interne RTE-Warteschlange die Daten im transformierten bzw. empfangenen Pufferformat, bis sie im Kontext der empfangenden Task deserialisiert und per OUT-Parameter ausgegeben werden.</p>"}, {"id": "FIG-a87b5d064d2ccb76", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation der AUTOSAR-Laufzeitumgebung (RTE). Das Diagramm stellt das Inter-ECU-Kommunikationsszenario für eine explizite Sender-Receiver-Kommunikation mit integrierter Datenkonvertierung und Transformation dar. Ein VariableDataPrototype mit Ereignissemantik (<code>queued swImplPolicy</code>) wird über Port <code>p</code> und Datenelement <code>e</code> übertragen. Die Empfangsseite verwendet den nicht-blockierenden Empfangsmechanismus über Argument (<code>dataReceivePointByArgument</code>) ohne WaitPoint am zugehörigen <code>DataReceivedEvent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Sender Application</code> (Software-Komponente auf Sender-ECU)\n</li><li><code>Sender&#x27;s RTE</code> (Dreifach unterteilte bzw. kollaborierende Lebenslinien für Applikationsschnittstelle, Datenkonvertierung und Transformation/Serialisierung)\n</li><li><code>Sender&#x27;s COM / Netwok / Receiver&#x27;s COM</code> (Kommunikationsinfrastruktur aus COM-Modulen und Netzwerkübertragung)\n</li><li><code>Receiver&#x27;s RTE</code> (Mehrfach unterteilte Lebenslinien für Retransformation, Warteschlangenverwaltung und Datenkonvertierung)\n</li><li><code>Receiver application</code> (Software-Komponente auf Empfänger-ECU)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen, interne Aufrufe und Statuswerte:</p>\n<ul class=\"fig-list\"><li><code>Rte_Receive_p_e()</code>: Nicht-blockierende Lese-API der RTE\n</li><li><code>Rte_Send_p_e()</code>: Sende-API der RTE\n</li><li>Interne Selbstaufrufe der RTE zur optionalen Datenkonvertierung auf Sender- und Empfängerseite\n</li><li><code>Xfrm_&lt;name&gt;()</code>: Aufruf des senderseitigen Transformers zur Serialisierung\n</li><li><code>Com_SendSignal()</code>: Signalübertragungs-API des COM-Moduls\n</li><li><code>Rte_COMCbk_&lt;sn&gt;()</code>: Signal-spezifischer COM-Callback an die RTE\n</li><li><code>Com_ReceiveSignal()</code>: API des COM-Moduls zum Abholen empfangener Daten\n</li><li><code>Xfrm_Inv_&lt;name&gt;()</code>: Aufruf des empfängerseitigen Transformers zur Deserialisierung\n</li><li>Rückgabewerte: <code>RTE_E_NO_DATA()</code>, <code>E_OK()</code>, <code>RTE_E_OK()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialisierung: Die empfängerseitige RTE-Warteschlange für das Ereignis <code>p_e</code> wird initialisiert/geleert (Notiz 1).\n</li><li>Vorzeitiger Leseversuch: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf; da die Warteschlange leer ist, liefert die RTE synchron <code>RTE_E_NO_DATA()</code> zurück (Notiz 2).\n</li><li>Sendevorgang: Die Sender-Applikation übergibt die Daten per <code>Rte_Send_p_e()</code>. Der Wert wird in die von der RTE allozierte Warteschlange kopiert (Notiz 3).\n</li><li>Senderseitige Konvertierung &amp; Transformation: Falls Datenkonvertierung konfiguriert ist, führt die RTE intern eine Konvertierung durch (Notiz 4). Anschließend wird der Eintrag über <code>Xfrm_&lt;name&gt;()</code> in ein Byte-Array transformiert (Notiz 5).\n</li><li>Übertragung an COM: Das serialisierte Array wird via <code>Com_SendSignal()</code> an den COM-Stack übergeben, der mit <code>E_OK()</code> quittiert; <code>Rte_Send_p_e()</code> kehrt mit <code>RTE_E_OK()</code> zur Sender-Applikation zurück.\n</li><li>COM-Benachrichtigung: Nach der Netzwerkübertragung ruft das Empfänger-COM die Callback-Funktion <code>Rte_COMCbk_&lt;sn&gt;()</code> der RTE auf (Notiz 6).\n</li><li>Warteschlangeneingang Empfänger: Die RTE ruft <code>Com_ReceiveSignal()</code> auf, quittiert mit <code>E_OK()</code> und reiht das empfangene Element <code>e</code> in die RTE-Warteschlange ein (Notiz 7).\n</li><li>Empfang, Retransformation &amp; Konvertierung: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf. Die RTE holt das Element aus der Queue und deserialisiert es mittels <code>Xfrm_Inv_&lt;name&gt;()</code> (Notiz 8). Falls konfiguriert, wird die empfangene Datendarstellung anschließend intern konvertiert (Notiz 9). Das Ergebnis wird im OUT-Parameter der Empfänger-Applikation gespeichert (Notiz 10) und der Aufruf mit <code>RTE_E_OK()</code> abgeschlossen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die vollständige Verarbeitungskette inklusive optionaler Datenkonvertierung und Transformation (Serialisierung/Deserialisierung) für gepufferte Inter-ECU-Kommunikation. Es verdeutlicht die funktionale Schichtenarchitektur innerhalb der RTE: Auf Senderseite folgt nach Pufferung in der RTE-Queue die optionale Konvertierung und danach die Transformation in ein Array für den COM-Stack. Auf Empfängerseite erfolgt nach dem Pufferungsschritt im COM-Callback die Deserialisierung und abschließende Konvertierung erst bei der Entnahme im Kontext des Leseaufrufs.</p>"}, {"id": "FIG-1e965f8a22b8ee18", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation der AUTOSAR-Laufzeitumgebung (RTE). Das Diagramm stellt das Inter-ECU-Kommunikationsszenario für eine explizite Sender-Receiver-Kommunikation mit integrierter Datenkonvertierung und Transformation dar. Ein VariableDataPrototype mit Ereignissemantik (<code>queued swImplPolicy</code>) wird über Port <code>p</code> und Datenelement <code>e</code> übertragen. Die Empfangsseite verwendet den nicht-blockierenden Empfangsmechanismus über Argument (<code>dataReceivePointByArgument</code>) ohne WaitPoint am zugehörigen <code>DataReceivedEvent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Sender Application</code> (Software-Komponente auf Sender-ECU)\n</li><li><code>Sender&#x27;s RTE</code> (Dreifach unterteilte bzw. kollaborierende Lebenslinien für Applikationsschnittstelle, Datenkonvertierung und Transformation/Serialisierung)\n</li><li><code>Sender&#x27;s COM / Netwok / Receiver&#x27;s COM</code> (Kommunikationsinfrastruktur aus COM-Modulen und Netzwerkübertragung)\n</li><li><code>Receiver&#x27;s RTE</code> (Mehrfach unterteilte Lebenslinien für Retransformation, Warteschlangenverwaltung und Datenkonvertierung)\n</li><li><code>Receiver application</code> (Software-Komponente auf Empfänger-ECU)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen, interne Aufrufe und Statuswerte:</p>\n<ul class=\"fig-list\"><li><code>Rte_Receive_p_e()</code>: Nicht-blockierende Lese-API der RTE\n</li><li><code>Rte_Send_p_e()</code>: Sende-API der RTE\n</li><li>Interne Selbstaufrufe der RTE zur optionalen Datenkonvertierung auf Sender- und Empfängerseite\n</li><li><code>Xfrm_&lt;name&gt;()</code>: Aufruf des senderseitigen Transformers zur Serialisierung\n</li><li><code>Com_SendSignal()</code>: Signalübertragungs-API des COM-Moduls\n</li><li><code>Rte_COMCbk_&lt;sn&gt;()</code>: Signal-spezifischer COM-Callback an die RTE\n</li><li><code>Com_ReceiveSignal()</code>: API des COM-Moduls zum Abholen empfangener Daten\n</li><li><code>Xfrm_Inv_&lt;name&gt;()</code>: Aufruf des empfängerseitigen Transformers zur Deserialisierung\n</li><li>Rückgabewerte: <code>RTE_E_NO_DATA()</code>, <code>E_OK()</code>, <code>RTE_E_OK()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialisierung: Die empfängerseitige RTE-Warteschlange für das Ereignis <code>p_e</code> wird initialisiert/geleert (Notiz 1).\n</li><li>Vorzeitiger Leseversuch: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf; da die Warteschlange leer ist, liefert die RTE synchron <code>RTE_E_NO_DATA()</code> zurück (Notiz 2).\n</li><li>Sendevorgang: Die Sender-Applikation übergibt die Daten per <code>Rte_Send_p_e()</code>. Der Wert wird in die von der RTE allozierte Warteschlange kopiert (Notiz 3).\n</li><li>Senderseitige Konvertierung &amp; Transformation: Falls Datenkonvertierung konfiguriert ist, führt die RTE intern eine Konvertierung durch (Notiz 4). Anschließend wird der Eintrag über <code>Xfrm_&lt;name&gt;()</code> in ein Byte-Array transformiert (Notiz 5).\n</li><li>Übertragung an COM: Das serialisierte Array wird via <code>Com_SendSignal()</code> an den COM-Stack übergeben, der mit <code>E_OK()</code> quittiert; <code>Rte_Send_p_e()</code> kehrt mit <code>RTE_E_OK()</code> zur Sender-Applikation zurück.\n</li><li>COM-Benachrichtigung: Nach der Netzwerkübertragung ruft das Empfänger-COM die Callback-Funktion <code>Rte_COMCbk_&lt;sn&gt;()</code> der RTE auf (Notiz 6).\n</li><li>Warteschlangeneingang Empfänger: Die RTE ruft <code>Com_ReceiveSignal()</code> auf, quittiert mit <code>E_OK()</code> und reiht das empfangene Element <code>e</code> in die RTE-Warteschlange ein (Notiz 7).\n</li><li>Empfang, Retransformation &amp; Konvertierung: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf. Die RTE holt das Element aus der Queue und deserialisiert es mittels <code>Xfrm_Inv_&lt;name&gt;()</code> (Notiz 8). Falls konfiguriert, wird die empfangene Datendarstellung anschließend intern konvertiert (Notiz 9). Das Ergebnis wird im OUT-Parameter der Empfänger-Applikation gespeichert (Notiz 10) und der Aufruf mit <code>RTE_E_OK()</code> abgeschlossen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die vollständige Verarbeitungskette inklusive optionaler Datenkonvertierung und Transformation (Serialisierung/Deserialisierung) für gepufferte Inter-ECU-Kommunikation. Es verdeutlicht die funktionale Schichtenarchitektur innerhalb der RTE: Auf Senderseite folgt nach Pufferung in der RTE-Queue die optionale Konvertierung und danach die Transformation in ein Array für den COM-Stack. Auf Empfängerseite erfolgt nach dem Pufferungsschritt im COM-Callback die Deserialisierung und abschließende Konvertierung erst bei der Entnahme im Kontext des Leseaufrufs.</p>"}, {"id": "FIG-aa11e861093ea859", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation der AUTOSAR-Laufzeitumgebung (RTE). Das Diagramm stellt das Inter-ECU-Kommunikationsszenario für eine explizite Sender-Receiver-Kommunikation mit integrierter Datenkonvertierung und Transformation dar. Ein VariableDataPrototype mit Ereignissemantik (<code>queued swImplPolicy</code>) wird über Port <code>p</code> und Datenelement <code>e</code> übertragen. Die Empfangsseite verwendet den nicht-blockierenden Empfangsmechanismus über Argument (<code>dataReceivePointByArgument</code>) ohne WaitPoint am zugehörigen <code>DataReceivedEvent</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Sender Application</code> (Software-Komponente auf Sender-ECU)\n</li><li><code>Sender&#x27;s RTE</code> (Dreifach unterteilte bzw. kollaborierende Lebenslinien für Applikationsschnittstelle, Datenkonvertierung und Transformation/Serialisierung)\n</li><li><code>Sender&#x27;s COM / Netwok / Receiver&#x27;s COM</code> (Kommunikationsinfrastruktur aus COM-Modulen und Netzwerkübertragung)\n</li><li><code>Receiver&#x27;s RTE</code> (Mehrfach unterteilte Lebenslinien für Retransformation, Warteschlangenverwaltung und Datenkonvertierung)\n</li><li><code>Receiver application</code> (Software-Komponente auf Empfänger-ECU)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen, interne Aufrufe und Statuswerte:</p>\n<ul class=\"fig-list\"><li><code>Rte_Receive_p_e()</code>: Nicht-blockierende Lese-API der RTE\n</li><li><code>Rte_Send_p_e()</code>: Sende-API der RTE\n</li><li>Interne Selbstaufrufe der RTE zur optionalen Datenkonvertierung auf Sender- und Empfängerseite\n</li><li><code>Xfrm_&lt;name&gt;()</code>: Aufruf des senderseitigen Transformers zur Serialisierung\n</li><li><code>Com_SendSignal()</code>: Signalübertragungs-API des COM-Moduls\n</li><li><code>Rte_COMCbk(ComUserCbkHandleId)</code>: Generischer COM-Callback mit Signal-Handle-ID zur Benachrichtigung der Empfänger-RTE\n</li><li><code>Com_ReceiveSignal()</code>: API des COM-Moduls zum Abholen empfangener Daten\n</li><li><code>Xfrm_Inv_&lt;name&gt;()</code>: Aufruf des empfängerseitigen Transformers zur Deserialisierung\n</li><li>Rückgabewerte: <code>RTE_E_NO_DATA()</code>, <code>E_OK()</code>, <code>RTE_E_OK()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialisierung: Die empfängerseitige RTE-Warteschlange für das Ereignis <code>p_e</code> wird initialisiert/geleert (Notiz 1).\n</li><li>Vorzeitiger Leseversuch: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf; da die Warteschlange leer ist, liefert die RTE synchron <code>RTE_E_NO_DATA()</code> zurück (Notiz 2).\n</li><li>Sendevorgang: Die Sender-Applikation übergibt die Daten per <code>Rte_Send_p_e()</code>. Der Wert wird in die von der RTE allozierte Warteschlange kopiert (Notiz 3).\n</li><li>Senderseitige Konvertierung &amp; Transformation: Falls Datenkonvertierung konfiguriert ist, führt die RTE intern eine Konvertierung durch (Notiz 4). Anschließend wird der Eintrag über <code>Xfrm_&lt;name&gt;()</code> in ein Byte-Array transformiert (Notiz 5).\n</li><li>Übertragung an COM: Das serialisierte Array wird via <code>Com_SendSignal()</code> an den COM-Stack übergeben, der mit <code>E_OK()</code> quittiert; <code>Rte_Send_p_e()</code> kehrt mit <code>RTE_E_OK()</code> zur Sender-Applikation zurück.\n</li><li>COM-Benachrichtigung: Nach der Netzwerkübertragung ruft das Empfänger-COM die Callback-Funktion <code>Rte_COMCbk(ComUserCbkHandleId)</code> der RTE auf (Notiz 6).\n</li><li>Warteschlangeneingang Empfänger: Die RTE ruft <code>Com_ReceiveSignal()</code> auf, quittiert mit <code>E_OK()</code> und reiht das empfangene Element <code>e</code> in die RTE-Warteschlange ein (Notiz 7).\n</li><li>Empfang, Retransformation &amp; Konvertierung: Die Empfänger-Applikation ruft <code>Rte_Receive_p_e()</code> auf. Die RTE holt das Element aus der Queue und deserialisiert es mittels <code>Xfrm_Inv_&lt;name&gt;()</code> (Notiz 8). Falls konfiguriert, wird die empfangene Datendarstellung anschließend intern konvertiert (Notiz 9). Das Ergebnis wird im OUT-Parameter der Empfänger-Applikation gespeichert (Notiz 10) und der Aufruf mit <code>RTE_E_OK()</code> abgeschlossen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die vollständige Verarbeitungskette inklusive optionaler Datenkonvertierung und Transformation (Serialisierung/Deserialisierung) für gepufferte Inter-ECU-Kommunikation. Es verdeutlicht die funktionale Schichtenarchitektur innerhalb der RTE: Auf Senderseite folgt nach Pufferung in der RTE-Queue die optionale Konvertierung und danach die Transformation in ein Array für den COM-Stack. Auf Empfängerseite erfolgt nach dem Pufferungsschritt im COM-Callback die Deserialisierung und abschließende Konvertierung erst bei der Entnahme im Kontext des Leseaufrufs.</p>"}], "trans": [{"from": "FIG-62f127f6ea4ffcff", "to": "FIG-706f2e28c75f8895", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Lebenslinien „Sender&#x27;s Transformer“ und „Receiver&#x27;s Transformer“ in der Kommunikationskette.\n</li><li>Einführung des Aufrufs von <code>Xfrm_&lt;name&gt;()</code> zur Datentransformation auf Senderseite vor der Übergabe an das COM-Modul.\n</li><li>Einführung des Aufrufs von <code>Xfrm_Inv_&lt;name&gt;()</code> zur Rücktransformation (Retransformation) auf Empfängerseite innerhalb von <code>Rte_Receive_p_e()</code>.\n</li><li>Anpassung von Notiz (5) auf Empfängerseite: Erweiterung um den Schritt „retransforms“.\n</li><li>Redaktionelle Anpassung: Notation aller API- und Funktionsaufrufe sowie Rückgabewerte im Sequenzdiagramm um runde Klammern <code>()</code> ergänzt.\n</li></ul>"}, {"from": "FIG-706f2e28c75f8895", "to": "FIG-a87b5d064d2ccb76", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neunummerierung und Erweiterung der Notizschritte von 6 auf 10 Einzelschritte.\n</li><li>Umbenennung der Transformer-Lebenslinien-Header in „Sender&#x27;s RTE“ bzw. „Receiver&#x27;s RTE“ (Kennzeichnung der Transformation als Bestandteil der RTE).\n</li><li>Ergänzung eines internen RTE-Selbstaufrufs auf Senderseite inklusive Notiz (4): Optionale Datenkonvertierung („the provided data is converted. Only if data conversion applies (optional)“).\n</li><li>Ergänzung von Notiz (3) für die senderseitige Pufferung („The data value provided by the sender is copied to the RTE allocated queue.“) und Notiz (5) für die Serialisierung („The queue entry is transformed to an array and transferred to the COM stack“).\n</li><li>Ergänzung eines internen RTE-Selbstaufrufs auf Empfängerseite inklusive Notiz (9): Optionale Datenkonvertierung empfangener Daten („The received data is converted. Only if data conversion applies (optional)“).\n</li><li>Umnummerierung der bisherigen Schritte (3) bis (6) zu den Schritten (6), (7), (8) und (10).\n</li></ul>"}, {"from": "FIG-a87b5d064d2ccb76", "to": "FIG-1e965f8a22b8ee18", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1e965f8a22b8ee18", "to": "FIG-aa11e861093ea859", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Änderung der Signatur des COM-Callbacks von <code>Rte_COMCbk_&lt;sn&gt;()</code> auf <code>Rte_COMCbk(ComUserCbkHandleId)</code> mit expliziter Übergabe der Callback-Handle-ID anstelle eines namensgebundenen Callbacks.\n</li></ul>"}]};
